import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises'
/**
 * Builds a Material Design Icons subset holding only the icons this app renders.
 *
 * `@mdi/font` ships ~7,450 icons: a 394KB woff2 (plus eot/ttf/woff copies of the same
 * glyphs) and a 409KB stylesheet that is one `content:` rule per icon. This app draws
 * a bit over a hundred of them. Every byte of the rest was downloaded, parsed and
 * thrown away on first load.
 *
 * So: find the icon names actually referenced, cut the font down to those glyphs, and
 * emit a stylesheet with only their rules.
 *
 * TWO sources of icon names, and missing the second is how this goes wrong quietly:
 *
 *   1. This repo's own source — `<v-icon icon="mdi-account">`, `mdi-` strings in
 *      component data, icon names in CSS `content:`.
 *   2. **Vuetify's own alias table** (`vuetify/lib/iconsets/mdi.js`). Component
 *      internals never name an icon in our source: the checkbox tick, the select
 *      dropdown chevron, the data-table sort arrow and the pagination chevrons all
 *      resolve through `$`-aliases inside Vuetify. Subset against our source alone and
 *      those become blank boxes in production while looking fine in dev, because dev
 *      serves the full font.
 *
 * Regenerated by the `dev` and `build` scripts (they chain it ahead of vite), so a
 * newly added icon cannot ship missing and dev matches production.
 * Output is committed so a deploy that skips the script still builds something correct.
 *
 * Run directly with: node scripts/build-mdi-subset.mjs
 */
import { createRequire } from 'node:module'
import { dirname, extname, join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import subsetFont from 'subset-font'

const require = createRequire(import.meta.url)
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')

const MDI_CSS = require.resolve('@mdi/font/css/materialdesignicons.css')
const MDI_WOFF2 = join(dirname(MDI_CSS), '../fonts/materialdesignicons-webfont.woff2')
const VUETIFY_ALIASES = require.resolve('vuetify/lib/iconsets/mdi.js')

const OUT_FONT = join(root, 'src/assets/fonts/mdi-subset.woff2')
const OUT_CSS = join(root, 'src/styles/mdi-subset.css')

const SCAN_DIRS = [join(root, 'src')]
const SCAN_EXTS = new Set(['.vue', '.js', '.ts', '.css', '.scss', '.html'])

/**
 * Names that look like icons but aren't glyphs, so that the "referenced but unknown"
 * warning stays meaningful — a name it does report is a genuine typo.
 *
 * `.mdi-spin`, `.mdi-rotate-45` and friends are modifiers; they live in the
 * stylesheet's trailer, which we copy over whole. `mdi-subset` is this script's own
 * output filename, picked up from the import in plugins/vuetify.js.
 */
const NOT_GLYPHS = /^mdi-(?:set|subset|spin|flip-[hv]|rotate-\d+|\d+px|dark|light|inactive)$/

/** Every `mdi-foo` token in a string. */
function iconNamesIn (text) {
  return text.match(/mdi-[a-z0-9]+(?:-[a-z0-9]+)*/g) ?? []
}

async function filesToScan (dir) {
  const entries = await readdir(dir, { withFileTypes: true, recursive: true })
  return entries
    .filter(entry => entry.isFile() && SCAN_EXTS.has(extname(entry.name)))
    .map(entry => join(entry.parentPath ?? entry.path, entry.name))
    // Our own output lives under src/, so without this the subset feeds itself: every
    // icon it emitted last run reads as a fresh reference this run, and an icon stays
    // in the font forever after its last real usage is deleted. Never drops an icon
    // that is still used — it just means the set only ever grows.
    .filter(file => file !== OUT_CSS)
}

/**
 * Splits the upstream stylesheet into the bits we keep verbatim and a name → codepoint
 * map. The header carries the `@font-face` and the shared `.mdi:before` box; the
 * trailer carries the size/rotate/flip/spin modifiers and their keyframes.
 */
function parseMdiCss (rawCss) {
  // The upstream stylesheet signs off with `/*# sourceMappingURL=materialdesignicons.css.map */`.
  // Stripped here rather than at the write below, because by then the annotation has
  // already been sliced into `trailer` and copied through verbatim — and in our output
  // it resolves against src/styles/, where no such map exists and none should: the
  // subset is generated, not compiled from a source we could map back to. Vite's dev
  // server reads the comment, fails the lookup, and logs a "Failed to load source map"
  // error on every request for the file — alarming, never fatal.
  const css = rawCss.replace(/\/\*#\s*sourceMappingURL=.*?\*\//g, '')

  const rule = /\.mdi-([a-z0-9-]+)::before\s*\{\s*content:\s*"\\([0-9A-Fa-f]+)";\s*\}/g
  const codepoints = new Map()
  let first = null
  let last = 0
  let match

  while ((match = rule.exec(css)) !== null) {
    if (first === null) {
      first = match.index
    }
    last = rule.lastIndex
    codepoints.set(match[1], Number.parseInt(match[2], 16))
  }
  if (first === null) {
    throw new Error(`No icon rules found in ${MDI_CSS}`)
  }

  // The base `.mdi:before, .mdi-set { … }` block, minus the upstream @font-face —
  // that one lists four formats and we replace it with a woff2-only one below.
  const header = css.slice(0, first).replace(/@font-face\s*\{[^}]*\}/, '').trim()

  return { codepoints, header, trailer: css.slice(last).trim() }
}

async function main () {
  const [css, fontBuffer, aliases] = await Promise.all([
    readFile(MDI_CSS, 'utf8'),
    readFile(MDI_WOFF2),
    readFile(VUETIFY_ALIASES, 'utf8'),
  ])

  const { codepoints, header, trailer } = parseMdiCss(css)

  const referenced = new Set()
  const sources = (await Promise.all(SCAN_DIRS.map(dir => filesToScan(dir)))).flat()
  for (const file of sources) {
    for (const name of iconNamesIn(await readFile(file, 'utf8'))) {
      referenced.add(name)
    }
  }
  const fromSource = referenced.size
  for (const name of iconNamesIn(aliases)) {
    referenced.add(name)
  }

  const keep = []
  const unknown = []
  for (const name of referenced) {
    const bare = name.replace(/^mdi-/, '')
    if (codepoints.has(bare)) {
      keep.push(bare)
    } else if (!NOT_GLYPHS.test(name)) {
      unknown.push(name)
    }
  }
  keep.sort()

  if (unknown.length > 0) {
    // Not fatal: an unrecognised name renders as nothing today too, with or without
    // this script. Worth saying out loud though — it is usually a typo.
    console.warn(
      `[mdi-subset] ${unknown.length} name(s) matched no icon and were skipped:\n  ${unknown.toSorted().join('\n  ')}`,
    )
  }

  // subset-font selects glyphs by the characters it is given, so map each codepoint
  // back to its character in the font's private use area.
  const text = keep.map(name => String.fromCodePoint(codepoints.get(name))).join('')
  const subset = await subsetFont(fontBuffer, text, { targetFormat: 'woff2' })

  await mkdir(dirname(OUT_FONT), { recursive: true })
  await writeFile(OUT_FONT, subset)

  const rules = keep
    .map(name => `.mdi-${name}::before { content: "\\${codepoints.get(name).toString(16).toUpperCase()}"; }`)
    .join('\n')

  await mkdir(dirname(OUT_CSS), { recursive: true })
  await writeFile(OUT_CSS, `/* GENERATED by scripts/build-mdi-subset.mjs — do not edit.
 * ${keep.length} of ${codepoints.size} Material Design Icons, the ones this app
 * actually renders. Re-run \`npm run build:icons\` after adding an icon — \`npm run
 * dev\` and \`npm run build\` both regenerate it first, so it cannot go stale.
 *
 * woff2 only. The upstream @font-face also lists eot, ttf and woff; no browser that
 * can run this app needs any of them, and listing them invites a preload pass or a
 * misconfigured proxy to fetch 3MB of duplicate glyphs.
 */
@font-face {
  font-family: "Material Design Icons";
  src: url("../assets/fonts/mdi-subset.woff2") format("woff2");
  font-weight: normal;
  font-style: normal;
  font-display: block;
}

${header}

${rules}

${trailer}
`)

  const kb = n => `${(n / 1024).toFixed(1)}KB`
  console.log(
    `[mdi-subset] ${keep.length} icons (${fromSource} referenced in src, rest from Vuetify aliases)\n`
    + `[mdi-subset] font ${kb(fontBuffer.length)} → ${kb(subset.length)}   `
    + `css ${kb(Buffer.byteLength(css))} → ${kb(Buffer.byteLength(await readFile(OUT_CSS, 'utf8')))}\n`
    + `[mdi-subset] wrote ${relative(root, OUT_FONT)} and ${relative(root, OUT_CSS)}`,
  )
}

await main()
